import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.Ki30n65y.js";const i="/depgate/screenshots/settings-artifact-cache.png",f=JSON.parse('{"title":"Artifact cache","description":"","frontmatter":{},"headers":[],"relativePath":"admin/artifact-cache.md","filePath":"admin/artifact-cache.md"}'),s={name:"admin/artifact-cache.md"};function d(c,e,n,h,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="artifact-cache" tabindex="-1">Artifact cache <a class="header-anchor" href="#artifact-cache" aria-label="Permalink to &quot;Artifact cache&quot;">​</a></h1><p>DepGate can keep a copy of each package file it downloads from a public registry on the local disk of each replica. The next request for the same file is served from that disk instead of the registry. Installs run at disk speed, public registries such as Maven Central stop rate-limiting you, and files already cached keep installing while a registry is down.</p><p>The production setups in <code>deploy/</code> start with the cache on. Elsewhere it is off until you give each replica a disk and switch it on in <strong>Settings → Artifact cache</strong>, as described in <a href="#turn-on-the-cache">Turn on the cache</a>.</p><p><img src="'+i+'" alt="Settings → Artifact cache"></p><h2 id="what-the-cache-does" tabindex="-1">What the cache does <a class="header-anchor" href="#what-the-cache-does" aria-label="Permalink to &quot;What the cache does&quot;">​</a></h2><p>Every download still goes through the full policy decision first. The cache only replaces the download from the registry, after the decision allowed it:</p><ol><li>DepGate authenticates the request, applies namespace protection and evaluates your policies, exactly as without the cache.</li><li>A blocked download gets its 403. The cache is not read.</li><li>For an allowed download from a public registry, DepGate serves the file from disk when it has it.</li><li>Otherwise DepGate streams the file from the registry to the client, and stores it on disk at the same time.</li></ol><p>Because the decision runs on every download, a policy you add later applies at once to files already in the cache. You never need to purge after a policy change or a malware match.</p><p>Each package file response carries an <code>X-DepGate-Cache</code> header:</p><table tabindex="0"><thead><tr><th>Value</th><th>Meaning</th></tr></thead><tbody><tr><td><code>HIT</code></td><td>Served from this replica&#39;s disk.</td></tr><tr><td><code>MISS</code></td><td>Downloaded from the registry and stored.</td></tr><tr><td><code>BYPASS</code></td><td>Downloaded from the registry and not stored: an internal remote, a file type the cache never keeps, a file over the size limit, the cache is off or full, or the same file is already being stored.</td></tr></tbody></table><p>The Dashboard counts, Monitoring and Log streaming see a cached download the same as any other.</p><h2 id="what-is-cached" tabindex="-1">What is cached <a class="header-anchor" href="#what-is-cached" aria-label="Permalink to &quot;What is cached&quot;">​</a></h2><p>Only files from <strong>public</strong> remotes are cached, including each ecosystem&#39;s <code>default</code> remote. Files from internal remotes, such as Artifactory or Nexus, are never cached. Metadata is never cached here; DepGate already caches it in Redis.</p><table tabindex="0"><thead><tr><th>Ecosystem</th><th>Cached</th><th>Never cached</th></tr></thead><tbody><tr><td>npm</td><td>Tarballs</td><td>Package documents</td></tr><tr><td>PyPI</td><td>Wheels, source archives, <code>.metadata</code> files</td><td>Simple index pages</td></tr><tr><td>Go</td><td><code>.zip</code>, <code>.mod</code>, <code>.info</code></td><td>Version lists</td></tr><tr><td>Maven</td><td>Release <code>.jar</code>, <code>.war</code>, <code>.aar</code>, <code>.pom</code>, <code>.module</code>, with their checksums and <code>.asc</code> signatures</td><td><code>maven-metadata.xml</code>, <code>-SNAPSHOT</code> versions</td></tr><tr><td>NuGet</td><td><code>.nupkg</code>, <code>.nuspec</code></td><td>Service index, registration, search</td></tr><tr><td>Cargo</td><td><code>.crate</code></td><td>Sparse index</td></tr><tr><td>Composer</td><td>Dist archives of tagged versions</td><td>Package metadata, <code>dev-</code> branches</td></tr><tr><td>RubyGems</td><td><code>.gem</code> files</td><td>Compact index, specs</td></tr></tbody></table><p>When a virtual repository searches several remotes, DepGate caches a file only when it already knows which remote serves it, for example from the package metadata. It never serves a public copy ahead of an internal remote it did not ask.</p><p>An npm version that the registry removed from the package is no longer served from the cache. In the other ecosystems, removed versions leave the cache when they expire (see <a href="#limits-and-expiry">Limits and expiry</a>).</p><h2 id="each-replica-has-its-own-cache" tabindex="-1">Each replica has its own cache <a class="header-anchor" href="#each-replica-has-its-own-cache" aria-label="Permalink to &quot;Each replica has its own cache&quot;">​</a></h2><p>Each replica caches on its own local disk; replicas share nothing. A new file is downloaded once per replica, no network file system or object storage is needed, and a replica restarted with an empty disk fills its cache again on its own. Never point two replicas at the same directory.</p><h2 id="limits-and-expiry" tabindex="-1">Limits and expiry <a class="header-anchor" href="#limits-and-expiry" aria-label="Permalink to &quot;Limits and expiry&quot;">​</a></h2><p>Each replica limits its cache by total size and by number of files, and removes files by age and by idle time. Change the limits in <strong>Settings → Artifact cache</strong> and choose <strong>Save</strong>: every replica applies them within seconds. The environment variables give the defaults; an empty field in Settings uses the default.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Variable (default)</th><th>Default</th></tr></thead><tbody><tr><td><strong>Size per pod</strong></td><td><code>ARTIFACT_CACHE_MAX_SIZE_GB</code></td><td>none: required before the cache can be turned on</td></tr><tr><td><strong>Files per pod</strong></td><td><code>ARTIFACT_CACHE_MAX_FILES</code></td><td><code>200000</code></td></tr><tr><td><strong>Expire after storing</strong></td><td><code>ARTIFACT_CACHE_MAX_AGE_DAYS</code></td><td><code>30</code> days (<code>0</code> = never)</td></tr><tr><td><strong>Expire when unused</strong></td><td><code>ARTIFACT_CACHE_MAX_IDLE_DAYS</code></td><td><code>7</code> days (<code>0</code> = never)</td></tr><tr><td><strong>Largest file stored</strong></td><td><code>ARTIFACT_CACHE_MAX_FILE_MB</code></td><td><code>1024</code> MB</td></tr></tbody></table><p>The <strong>Directory</strong> is set by <code>ARTIFACT_CACHE_DIR</code> only. It must be a volume mounted at the same path on every replica, which the web interface cannot check or create.</p><ul><li>Each replica never uses more than the free space of its disk, minus a reserve of 5 % of the disk (at most 10 GB). When that is less than <strong>Size per pod</strong>, the table of pods marks the replica&#39;s size with <strong>disk</strong>.</li><li>A lower size or file limit removes the least recently used files at once. A shorter expiry applies from the next download.</li><li>An expired file is never served. The next request downloads it again.</li><li>When the size or the file count reaches 95 % of its limit, DepGate removes expired files, then the least recently used files, until both are at 90 %. This also runs every 10 minutes.</li><li>A file larger than <strong>Largest file stored</strong> is served but not stored.</li></ul><h3 id="sizing-the-limits" tabindex="-1">Sizing the limits <a class="header-anchor" href="#sizing-the-limits" aria-label="Permalink to &quot;Sizing the limits&quot;">​</a></h3><ul><li><strong>Size.</strong> Set <strong>Size per pod</strong> below the size of the volume, leaving room for files being written: 80 GB on a 100 GB volume is a good start. The value is in GB of 1024³ bytes.</li><li><strong>Files.</strong> The default of 200,000 files suits most teams. Raise it on a large volume with many small packages, such as npm.</li><li><strong>Age and idle time.</strong> The defaults keep a team&#39;s working set warm. Shorten the idle time if the disk fills with versions from old branches.</li></ul><p>Watch <strong>Settings → Artifact cache</strong> for a few days after you turn the cache on. A replica that sits at its size limit with a low hit rate needs a bigger volume.</p><h2 id="turn-on-the-cache" tabindex="-1">Turn on the cache <a class="header-anchor" href="#turn-on-the-cache" aria-label="Permalink to &quot;Turn on the cache&quot;">​</a></h2><ol><li>Give each replica a volume on local SSD. The Compose setups in <code>deploy/</code> mount a named volume at <code>/var/lib/depgate/artifacts</code>; the Kubernetes manifests give each pod an <code>emptyDir</code>. See <a href="/depgate/install/kubernetes#artifact-cache">Install on Kubernetes → Artifact cache</a>.</li><li>Open <strong>Settings → Artifact cache</strong>, enter <strong>Size per pod</strong> (below the volume size) and choose <strong>Save</strong>.</li><li>Turn on the switch next to <strong>Artifact cache</strong>. Every replica switches within seconds and is listed with the state <strong>On</strong>.</li></ol><p>To configure everything with environment variables instead, set <code>ARTIFACT_CACHE_ENABLED=true</code> and <code>ARTIFACT_CACHE_MAX_SIZE_GB</code> in the setup&#39;s <code>.env</code> (or the ConfigMap) and restart.</p><p>If <code>ARTIFACT_CACHE_ENABLED</code> is <code>true</code> without <code>ARTIFACT_CACHE_MAX_SIZE_GB</code>, DepGate does not start and says which variable is missing. If the directory is missing or not writable, DepGate starts with the cache off, shows the error on the <strong>Artifact cache</strong> tab, and serves every download from the registry.</p><h2 id="switch-the-cache-off-or-on" tabindex="-1">Switch the cache off or on <a class="header-anchor" href="#switch-the-cache-off-or-on" aria-label="Permalink to &quot;Switch the cache off or on&quot;">​</a></h2><p>The switch next to <strong>Artifact cache</strong> in <strong>Settings → Artifact cache</strong> turns the cache on or off on every replica within seconds, and overrides <code>ARTIFACT_CACHE_ENABLED</code>. Every change in Settings is recorded in the <a href="./audit-log">Audit Log</a> as <strong>Artifact cache settings changed</strong>.</p><ul><li><strong>Off.</strong> Every download streams from the registry, as without the cache. Stored files stay on disk; they still expire, and you can still purge them. To free the disk at once, clear the cache before you switch it off.</li><li><strong>On.</strong> Files stored before you switched it off are served again, unless they expired.</li><li><strong>Reset</strong>, next to the switch, removes the override, so <code>ARTIFACT_CACHE_ENABLED</code> decides again.</li></ul><p>The switch can be turned on once <strong>Size per pod</strong> is set.</p><h2 id="check-the-cache" tabindex="-1">Check the cache <a class="header-anchor" href="#check-the-cache" aria-label="Permalink to &quot;Check the cache&quot;">​</a></h2><p>Open <strong>Settings → Artifact cache</strong> (Security role). The tab shows the switch and the limits, with each limit&#39;s default, and under <strong>Pods</strong> one row per running replica: its state, the space and files it uses, and the share of downloads served from the cache in the last 24 hours. Replicas report every 15 seconds; one that stops reporting leaves the table after a minute.</p><p>Prometheus metrics on each replica:</p><table tabindex="0"><thead><tr><th>Metric</th><th>Meaning</th></tr></thead><tbody><tr><td><code>depgate_artifact_cache_requests_total{ecosystem,result}</code></td><td>Artifact downloads by result: <code>hit</code>, <code>miss</code>, <code>bypass</code>.</td></tr><tr><td><code>depgate_artifact_cache_size_bytes</code></td><td>Bytes in this replica&#39;s cache.</td></tr><tr><td><code>depgate_artifact_cache_files</code></td><td>Files in this replica&#39;s cache.</td></tr><tr><td><code>depgate_artifact_cache_evicted_total{reason}</code></td><td>Files removed, by reason: <code>age</code>, <code>idle</code>, <code>size</code>, <code>files</code>, <code>purge</code>.</td></tr></tbody></table><h2 id="purge" tabindex="-1">Purge <a class="header-anchor" href="#purge" aria-label="Permalink to &quot;Purge&quot;">​</a></h2><p>You can remove one package, one version of a package, or every file, from the cache of every running replica.</p><ol><li>Open <strong>Settings → Artifact cache</strong>.</li><li>Under <strong>Purge</strong>, choose the <strong>Ecosystem</strong>, and enter the <strong>Package</strong> name as the ecosystem spells it: <code>lodash</code>, <code>org.example:core</code>, <code>github.com/acme/module</code>, <code>vendor/name</code>.</li><li>Enter a <strong>Version</strong> to remove only that version, or leave it empty for every version.</li><li>Choose <strong>Purge</strong>, then confirm.</li></ol><p>To clear everything, type the phrase shown next to <strong>Clear everything</strong> and choose <strong>Clear</strong>.</p><p>Every running replica applies the purge within seconds. A replica that is down at the time misses it; its files still expire, and the policy decision still runs before every download. Each purge is recorded in the <a href="./audit-log">Audit Log</a> as <strong>Artifact cache purged</strong>, with who sent it and what it removed.</p><p>The same actions are available in the REST API: <code>POST /api/artifact-cache/purge</code> with <code>{ &quot;ecosystem&quot;: &quot;npm&quot;, &quot;package&quot;: &quot;lodash&quot;, &quot;version&quot;: &quot;4.17.21&quot; }</code> or <code>{ &quot;all&quot;: true }</code>, <code>PUT /api/artifact-cache/settings</code> with <code>{ &quot;enabled&quot;: true }</code>, <code>false</code> or <code>null</code>, and <code>GET /api/artifact-cache/status</code>.</p><h2 id="when-something-fails" tabindex="-1">When something fails <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;When something fails&quot;">​</a></h2><p>The cache never adds a way for a download to fail. Each failure falls back to the registry.</p><table tabindex="0"><thead><tr><th>Situation</th><th>What happens</th></tr></thead><tbody><tr><td>Directory missing or not writable</td><td>The replica starts with the cache off and shows the error. Downloads are <code>BYPASS</code>.</td></tr><tr><td>Read error on a cached file</td><td>That request is downloaded from the registry. An error in the middle of a download closes the connection, and the client retries.</td></tr><tr><td>Disk full or write error</td><td>The file is still served, and old files are removed to make room.</td></tr><tr><td>Redis down</td><td>The cache keeps working. Only purges wait for Redis.</td></tr><tr><td>Registry down, file cached</td><td>The file is served from the cache.</td></tr><tr><td>Registry down, file not cached</td><td>As without the cache: <code>502</code>, or <code>503</code> while DepGate pauses requests to that registry.</td></tr></tbody></table><p>A replica that stops in the middle of storing a file removes the partial file at its next start. A partial file is never served.</p>',48)])])}const u=t(s,[["render",d]]);export{f as __pageData,u as default};
